namespace ghidra.app.util;





using ghidra.app.plugin.core.navigation.locationreferences;
using ghidra.docking.settings;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.util.datastruct;
using ghidra.util.exception;
using ghidra.util.table;
using ghidra.util.table.field;
using ghidra.util.task;

public class FunctionXrefsTableModel : ReferencesFromTableModel {

	private Function function;
	private bool showAllThunkXrefs;

	public FunctionXrefsTableModel(Function function, Supplier<Collection<Reference>> directRefs,
			ServiceProvider sp, Program program) : base(directRefs, sp, program)
    {
		this.function = function;

		addTableColumn(new IsThunkTableColumn());
	}

	/* @Override */
	protected void doLoad(Accumulator<ReferenceEndpoint> accumulator, TaskMonitor monitor)
    {

		if (!showAllThunkXrefs) {
			base.doLoad(accumulator, monitor); // only include the supplied refs from our parent
			return;
		}

		Function baseFunction = function;
		if (function.isThunk()) {
			baseFunction = function.getThunkedFunction(true);
		}

		doLoadThunkFunctionReferences(baseFunction, accumulator, monitor);
	}

	private void doLoadThunkFunctionReferences(Function baseFunction,
			Accumulator<ReferenceEndpoint> accumulator, TaskMonitor monitor)
    {

		addReferences(accumulator, baseFunction.getEntryPoint());

		Address[] thunks = baseFunction.getFunctionThunkAddresses(true);
		if (thunks == null) {
			return; // no thunks
		}

		foreach (Address address in thunks) {
			monitor.checkCancelled();
			addReferences(accumulator, address);
		}
	}

	private void addReferences(Accumulator<ReferenceEndpoint> accumulator, Address address) {

		ProgramLocation location = new ProgramLocation(program, address);
		Set<Reference> refs = XReferenceUtils.getAllXrefs(location);
		foreach (Reference @ref in refs) {
			bool offcut = ReferenceUtils.isOffcut(program, @ref.getToAddress());
			accumulator.add(new ThunkIncomingReferenceEndpoint(@ref, offcut));
		}
	}

	void toggleShowAllThunkXRefs() {
		this.showAllThunkXrefs = !showAllThunkXrefs;
		reload();
	}

//=================================================================================================
// Inner Classes
//=================================================================================================

	private class ThunkIncomingReferenceEndpoint : IncomingReferenceEndpoint {

		public ThunkIncomingReferenceEndpoint(Reference r, bool isOffcut) : base(r, isOffcut)
    {
		}

	}

	private class IsThunkTableColumn : AbstractProgramBasedDynamicTableColumn<ReferenceEndpoint, string> {

		/* @Override */
		public string getColumnName() {
			return "Thunk?";
		}

		/* @Override */
		public string getValue(ReferenceEndpoint rowObject, Settings settings, Program data,
				ServiceProvider sp)
    {

			Address toAddress = rowObject.getReference().getToAddress();
			FunctionManager fm = program.getFunctionManager();
			Function f = fm.getFunctionAt(toAddress);
			if (f != null && f.isThunk()) {
				return "thunk";
			}
			return "";
		}

	}
}
